-- Foreign keys
-- Анхны MySQL: "turul", "niilvvlegch" хүснэгт dump-д ороогүй тул FK хасагдсан.

ALTER TABLE "baraa"
  ADD CONSTRAINT baraa_ibfk_2 FOREIGN KEY ("company") REFERENCES "uildwerlegch" ("id");

ALTER TABLE "hariltsagch"
  ADD CONSTRAINT hariltsagch_ibfk_1 FOREIGN KEY ("turul") REFERENCES "turul_hariltsagch" ("id");

ALTER TABLE "vldegdel"
  ADD CONSTRAINT vldegdel_ibfk_1 FOREIGN KEY ("baraanii_id") REFERENCES "baraa" ("id");

ALTER TABLE "vne"
  ADD CONSTRAINT vne_ibfk_1 FOREIGN KEY ("baraanii_id") REFERENCES "baraa" ("id"),
  ADD CONSTRAINT vne_ibfk_2 FOREIGN KEY ("turul_id") REFERENCES "turul_hariltsagch" ("id");


